# /// script
# requires-python = ">=3.12"
# ///
"""Prepare a crawl-local copy of the pinned extension with local proof export."""

import errno
import time
import hashlib
import tempfile
import json
import os
import shutil
from pathlib import Path
from abx_plugins.plugins.base.utils import load_config

config = load_config()
if config.TLSNOTARY_ENABLED:
    if config.TLSNOTARY_EXTENSION_DIR:
        # A rebuilt MPC protocol requires its matching verifier. Accept only an
        # explicitly configured local build, never extension code from a remote
        # verifier, and verify its exported bundles before bypassing release patches.
        source = Path(config.TLSNOTARY_EXTENSION_DIR).resolve(strict=True)
        build = json.loads((source / "archivebox-build.json").read_text())
        for name, digest in build["bundles"].items():
            target = (source / name).resolve(strict=True)
            if not target.is_relative_to(source):
                raise ValueError("TLSNotary build manifest path escapes extension")
            if hashlib.sha256(target.read_bytes()).hexdigest() != digest:
                raise ValueError(
                    f"TLSNotary source-built extension checksum mismatch: {name}",
                )
        for required in (
            "offscreen.bundle.js",
            "background.bundle.js",
            "tlsn_wasm_bg.wasm",
        ):
            if required not in build["bundles"]:
                raise ValueError(
                    f"TLSNotary source-built extension manifest omits {required}",
                )
        metadata_path = Path(config.CRAWL_DIR) / "tlsnotary" / "extension.json"
        metadata_path.parent.mkdir(parents=True, exist_ok=True)
        metadata_path.write_text(
            json.dumps(
                {"name": "tlsnotary", "unpacked_path": str(source), "build": build},
            ),
        )
        raise SystemExit(0)
    metadata = json.loads(
        (
            Path(os.environ["CHROMEWEBSTORE_EXTENSIONS_DIR"])
            / "tlsnotary.extension.json"
        ).read_text(),
    )
    source = Path(metadata["unpacked_path"])
    if json.loads((source / "manifest.json").read_text())["version"] != "0.1.0.1501":
        raise RuntimeError("TLSNotary export patch requires release 0.1.0.1501")
    destination = Path(config.PERSONAS_DIR) / ".tlsnotary" / "0.1.0.1501-export2"
    destination.parent.mkdir(parents=True, exist_ok=True)
    with (destination.parent / "prepare.lock").open("a+b") as lock:
        if os.name == "nt":
            import msvcrt

            if lock.seek(0, 2) == 0:
                lock.write(b"\0")
                lock.flush()
            lock.seek(0)
            while True:
                try:
                    msvcrt.locking(lock.fileno(), msvcrt.LK_NBLCK, 1)
                    break
                except OSError as error:
                    if error.errno not in (errno.EACCES, errno.EDEADLK):
                        raise
                    time.sleep(1)
        else:
            import fcntl

            fcntl.flock(lock, fcntl.LOCK_EX)
        with tempfile.TemporaryDirectory(
            prefix=".prepare-",
            dir=destination.parent,
        ) as stage:
            staging = Path(stage)
            shutil.copytree(source, staging, dirs_exist_ok=True)
            bundle = staging / "offscreen.bundle.js"
            script = bundle.read_text()
            # ZIP pinned in config.json; SessionManager.ts:354-381. These fields go only
            # to the local caller, never to the remote verifier's sessionData.
            old = (
                'return p("COMPLETE",1,"Complete"),w}finally{await r.cleanupProver(b)}'
            )
            new = 'return p("COMPLETE",1,"Complete"),{...w,localProof:{openings:v,commit:f,recv:Array.from(r.getRecvBytes(b))}}}finally{await r.cleanupProver(b)}'
            if script.count(old) != 1:
                raise RuntimeError(
                    "TLSNotary export patch does not match pinned release",
                )
            script = script.replace(old, new).replace(
                'f&&u.debug("reveal openings",v),',
                "",
            )
            bundle.write_text(script)
            # Let Chrome position the approval popup. Centering on an oversized headless
            # window (ArchiveBox's default) can put it outside the virtual screen.
            background = staging / "background.bundle.js"
            background_script = background.read_text()
            position = "height:this.POPUP_HEIGHT,left:a,top:d,focused:!0"
            if background_script.count(position) != 1:
                raise RuntimeError(
                    "TLSNotary popup patch does not match pinned release",
                )
            background_script = background_script.replace(
                position,
                "height:this.POPUP_HEIGHT,focused:!0",
            )
            managed_position = "width:t,height:s,left:e,top:i}"
            if background_script.count(managed_position) != 1:
                raise RuntimeError(
                    "TLSNotary managed-window patch does not match pinned release",
                )
            background.write_text(
                background_script.replace(managed_position, "width:t,height:s}"),
            )
            if destination.exists():
                if (destination / "offscreen.bundle.js").read_text() != script or (
                    destination / "background.bundle.js"
                ).read_bytes() != background.read_bytes():
                    raise RuntimeError(
                        "Prepared extension differs from the pinned version; use a fresh persona cache",
                    )
            else:
                staging.rename(destination)
    metadata_path = Path(config.CRAWL_DIR) / "tlsnotary" / "extension.json"
    metadata_path.parent.mkdir(parents=True, exist_ok=True)
    metadata_path.write_text(
        json.dumps(
            {
                "name": "tlsnotary",
                "unpacked_path": str(destination.resolve()),
                "version": "0.1.0.1501",
                "export_patch": 2,
                "bundle_sha256": hashlib.sha256(script.encode()).hexdigest(),
            },
        ),
    )

#!/usr/bin/env -S abxpkg run --script --deps-from=../chrome/config.json:required_binaries,./config.json:required_binaries node
// /// script
// ///
/**
 * Claude for Chrome Extension - Configuration
 *
 * Configures the Claude for Chrome extension with the ANTHROPIC_API_KEY after
 * Chrome session starts. Injects the API key into chrome.storage.local so the
 * extension can authenticate without manual OAuth login.
 *
 * Priority: 96 (after chrome_launch at 90)
 * Hook: on_Crawl (runs once per crawl, not per snapshot)
 *
 * Note: Claude for Chrome normally uses OAuth PKCE (claude.com login).
 * This hook attempts to inject the API key directly into extension storage.
 * If this doesn't work with your extension version, you may need to log in
 * manually via the Chrome session before archiving.
 */

const path = require("path");
const fs = require("fs");
const {
  PROCESS_EXIT_SKIPPED,
  ensureNodeModuleResolution,
  getEnv,
  getEnvBool,
  loadConfig,
} = require("../base/utils.js");
ensureNodeModuleResolution(module);

const {
  waitForChromeSessionState,
  findExtensionMetadataByName,
  connectToBrowserEndpoint,
  resolvePuppeteerModule,
} = require("../chrome/chrome_utils.js");

// Check if enabled
if (!getEnvBool("CLAUDECHROME_ENABLED", false)) {
  console.log("CLAUDECHROME_ENABLED=False");
  process.exit(PROCESS_EXIT_SKIPPED);
}

const puppeteer = resolvePuppeteerModule();

const PLUGIN_DIR = path.basename(__dirname);
const hookConfig = loadConfig();
const CRAWL_DIR = path.resolve((hookConfig.CRAWL_DIR || ".").trim());
const OUTPUT_DIR = path.join(CRAWL_DIR, PLUGIN_DIR);
if (!fs.existsSync(OUTPUT_DIR)) {
  fs.mkdirSync(OUTPUT_DIR, { recursive: true });
}
process.chdir(OUTPUT_DIR);

function getCrawlChromeSessionDir() {
  return path.join(path.resolve(hookConfig.CRAWL_DIR || "."), "chrome");
}

const CHROME_SESSION_DIR = getCrawlChromeSessionDir();
const CONFIG_MARKER = path.join(CHROME_SESSION_DIR, ".claudechrome_configured");

async function configureClaudeChrome() {
  // Check if already configured in this session
  if (fs.existsSync(CONFIG_MARKER)) {
    console.error("[*] Claude for Chrome already configured in this session");
    return { success: true, skipped: true };
  }

  const apiKey = getEnv("ANTHROPIC_API_KEY");
  if (!apiKey) {
    console.warn(
      "[!] ANTHROPIC_API_KEY not set, skipping Claude for Chrome config"
    );
    return { success: false, error: "ANTHROPIC_API_KEY not set" };
  }

  console.error("[*] Configuring Claude for Chrome extension...");
  console.error(`[*]   API Key: ${apiKey.slice(0, 8)}...${apiKey.slice(-4)}`);

  try {
    const chromeSession = await waitForChromeSessionState(CHROME_SESSION_DIR, {
      timeoutMs: 10000,
      requireBrowserReady: true,
    });
    if (!chromeSession?.cdpUrl) {
      throw new Error("No Chrome session found (chrome plugin must run first)");
    }
    const { cdpUrl } = chromeSession;
    const browser = await connectToBrowserEndpoint(puppeteer, cdpUrl, {
      defaultViewport: null,
    });

    try {
      // Wake up the extension by visiting a page
      console.error("[*] Waking up extension...");
      const triggerPage = await browser.newPage();
      try {
        await triggerPage.goto("https://www.google.com", {
          waitUntil: "domcontentloaded",
          timeout: 10000,
        });
        await new Promise((r) => setTimeout(r, 3000));
      } catch (e) {
        console.warn(`[!] Trigger page: ${e.message}`);
      }
      try {
        await triggerPage.close();
      } catch (e) {}

      // Read extension metadata
      const extensions = chromeSession.extensions || [];
      const claudeExt = findExtensionMetadataByName(extensions, "claudechrome");
      if (!claudeExt || !claudeExt.id) {
        console.error(
          "[*] Claude for Chrome extension not found in browser.json"
        );
        return { success: true, skipped: true };
      }

      const extensionId = claudeExt.id;
      console.error(`[*] Claude for Chrome Extension ID: ${extensionId}`);

      // Try to find an extension page to inject config
      // The extension may have a popup, options page, or side panel
      const pages = await browser.pages();
      let extPage = pages.find((p) =>
        p.url().startsWith(`chrome-extension://${extensionId}`)
      );

      if (!extPage) {
        // Try opening the extension's popup or background page
        extPage = await browser.newPage();
        try {
          // Try common extension pages
          for (const pagePath of [
            "popup.html",
            "index.html",
            "options.html",
            "sidepanel.html",
          ]) {
            try {
              await extPage.goto(
                `chrome-extension://${extensionId}/${pagePath}`,
                {
                  waitUntil: "domcontentloaded",
                  timeout: 5000,
                }
              );
              if (
                extPage.url().startsWith(`chrome-extension://${extensionId}`)
              ) {
                break;
              }
            } catch (e) {
              continue;
            }
          }
        } catch (e) {
          console.error(`[*] Could not open extension page: ${e.message}`);
        }
      }

      if (
        !extPage ||
        !extPage.url().startsWith(`chrome-extension://${extensionId}`)
      ) {
        console.warn(
          "[!] Could not access extension context for config injection"
        );
        // Still mark as configured so we don't retry
        fs.writeFileSync(
          CONFIG_MARKER,
          JSON.stringify(
            {
              timestamp: new Date().toISOString(),
              extensionId,
              configured: false,
              note:
                "Could not access extension context - user may need to log in manually",
            },
            null,
            2
          )
        );
        return { success: true, skipped: true };
      }

      // Inject API key into chrome.storage.local
      // Claude for Chrome internally uses the Anthropic SDK, so we try to
      // set the API key in the storage format it expects
      const result = await extPage.evaluate((key) => {
        return new Promise((resolve) => {
          if (typeof chrome === "undefined" || !chrome.storage) {
            resolve({ success: false, error: "chrome.storage not available" });
            return;
          }

          // Try setting the API key in various storage formats the extension might use
          const configData = {
            anthropicApiKey: key,
            apiKey: key,
            api_key: key,
          };

          chrome.storage.local.set(configData, () => {
            if (chrome.runtime.lastError) {
              resolve({
                success: false,
                error: chrome.runtime.lastError.message,
              });
            } else {
              resolve({ success: true });
            }
          });
        });
      }, apiKey);

      try {
        await extPage.close();
      } catch (e) {}

      if (result.success) {
        console.error(
          "[+] Claude for Chrome API key injected into extension storage"
        );
      } else {
        console.warn(`[!] Storage injection failed: ${result.error}`);
        console.warn(
          "[!] User may need to log in to claude.com manually in the Chrome session"
        );
      }

      // Write marker file
      fs.writeFileSync(
        CONFIG_MARKER,
        JSON.stringify(
          {
            timestamp: new Date().toISOString(),
            extensionId,
            configured: result.success,
          },
          null,
          2
        )
      );

      return { success: true };
    } finally {
      browser.disconnect();
    }
  } catch (e) {
    return { success: false, error: `${e.name}: ${e.message}` };
  }
}

async function main() {
  console.log("Claude for Chrome configuration started");
  const result = await configureClaudeChrome();

  if (result.skipped) {
    process.exit(0);
  } else if (result.success) {
    console.error("[+] Claude for Chrome configuration complete");
    process.exit(0);
  } else {
    console.error(`ERROR: ${result.error}`);
    // Non-fatal - extension may still work with manual login
    process.exit(0);
  }
}

main().catch((e) => {
  console.error(`Fatal error: ${e.message}`);
  process.exit(1);
});

#!/usr/bin/env -S abxpkg run --script --deps-from=../chrome/config.json:required_binaries,./config.json:required_binaries python3
# /// script
# requires-python = ">=3.12"
# ///

import os
import errno
import json
import shutil
import tempfile
from pathlib import Path

from abx_plugins.plugins.base.utils import load_config, write_text_atomic


EXTENSION_NAME = "archivewebpage"

extensions_dir = Path(os.environ["CHROMEWEBSTORE_EXTENSIONS_DIR"])
metadata_path = extensions_dir / f"{EXTENSION_NAME}.extension.json"
if not metadata_path.is_file():
    raise RuntimeError(f"Chrome extension metadata was not prepared: {metadata_path}")
metadata = json.loads(metadata_path.read_text(encoding="utf-8"))
manifest_path = Path(metadata["unpacked_path"]) / "manifest.json"
if not manifest_path.is_file():
    raise RuntimeError(f"Chrome extension manifest was not prepared: {manifest_path}")

config = load_config()
source = manifest_path.parent
version = json.loads(manifest_path.read_text())["version"]
if version != "0.17.0":
    raise RuntimeError("ArchiveWeb.page service-worker patch requires release 0.17.0")
script = (source / "bg.js").read_text()
old = '"Network.setBypassServiceWorker",{bypass:!0}'
if script.count(old) != 1:
    raise RuntimeError(
        "ArchiveWeb.page service-worker patch does not match pinned release",
    )
# AWP bypasses workers in every recording session, including child frames.
# That changes what the page does: ReplayWeb.page's worker-owned replay URLs
# fall through to the website, recursively embed it, and eventually wedge the
# renderer. Preserve normal worker handling so all extractors see the actual
# page; AWP still records its Network response events and bodies.
script = script.replace(old, '"Network.setBypassServiceWorker",{bypass:!1}')
# Worker-generated responses have no bytes transferred over the network, even
# when their body is nonempty. AWP's wire-byte gate otherwise silently drops
# these bodies from the WACZ after the live page has rendered successfully.
old_payload = (
    'e.encodedDataLength&&(r=yield this.fetchPayloads(e,t,i,"Network.getResponseBody"))'
)
if script.count(old_payload) != 1:
    raise RuntimeError(
        "ArchiveWeb.page worker-response patch does not match pinned release",
    )
script = script.replace(
    old_payload,
    '(e.encodedDataLength||t.fromServiceWorker)&&(r=yield this.fetchPayloads(e,t,i,"Network.getResponseBody"))',
)
# A top-level worker response can commit its frame before loadingFinished,
# without passing through Fetch interception. Removing that pending response
# here archives a null body and prevents Network.getResponseBody from ever
# running. Only commit an already acquired payload; leave the ordinary loading
# completion path responsible for responses whose bodies are still pending.
old_document = (
    "const i=this.removeReqResp(this.loaderId);return i&&this.fullCommit(i,e),!0"
)
if script.count(old_document) != 1:
    raise RuntimeError(
        "ArchiveWeb.page document-response patch does not match pinned release",
    )
script = script.replace(
    old_document,
    "const i=this.pendingReqResp(this.loaderId,!0);"
    "return i&&i.payload&&(this.removeReqResp(this.loaderId),this.fullCommit(i,e)),!0",
)
# CDP reuses the network request ID across redirects. The old response's empty
# payload and Fetch flag must not masquerade as the next response's acquired
# body. Keep the redirect record, then start a fresh request/response lifecycle.
redirect_patches = (
    (
        "const t=this.pendingReqResp(e.requestId);let i=null;",
        "let t=this.pendingReqResp(e.requestId);let i=null;",
    ),
    (
        "i=t.toDBRecord(null,this.pageInfo,this.archiveCookies)}t.fillRequest(e)",
        "i=t.toDBRecord(null,this.pageInfo,this.archiveCookies);"
        "this.removeReqResp(e.requestId);t=this.pendingReqResp(e.requestId)}t.fillRequest(e)",
    ),
)
for before, after in redirect_patches:
    if script.count(before) != 1:
        raise RuntimeError(
            "ArchiveWeb.page redirect-response patch does not match pinned release",
        )
    script = script.replace(before, after)
# AWP has one status port per recorder. Concurrent helpers overwrite it, and
# closing either helper can strand the other handshake. Subscribe every live
# popup independently; moving or disconnecting a popup removes only that port.
popup_patches = (
    (
        'case"startUpdates":i=r.tabId,self.recorders[i]&&(self.recorders[i].port=e,self.recorders[i].doUpdateStatus()),e.postMessage(yield og(pg));break;',
        """case"startUpdates": {
            const previous = self.recorders[i];
            previous?.popupPorts?.delete(e);
            if (previous?.port === e) previous.port = null;
            i = r.tabId;
            const recorder = self.recorders[i];
            if (recorder) {
                recorder.popupPorts ??= new Set(recorder.port ? [recorder.port] : []);
                recorder.popupPorts.add(e);
                recorder.port = e;
                recorder.doUpdateStatus();
            }
            e.postMessage(yield og(pg));
            break;
        }""",
    ),
    (
        "this.port){const t=this.getStatusMsg();this.port.postMessage(t)}",
        "(this.popupPorts?.size||this.port)){const t=this.getStatusMsg();for(const p of this.popupPorts||[this.port])p.postMessage(t)}",
    ),
    (
        "self.recorders[i]&&(self.recorders[i].port=null)",
        "self.recorders[i]?.popupPorts?.delete(e);if(self.recorders[i]?.port===e)self.recorders[i].port=null",
    ),
)
for before, after in popup_patches:
    if script.count(before) != 1:
        raise RuntimeError(
            "ArchiveWeb.page popup-port patch does not match pinned release",
        )
    script = script.replace(before, after)
destination = (
    Path(config.PERSONAS_DIR) / ".archivewebpage" / f"{version}-service-workers5"
)
destination.parent.mkdir(parents=True, exist_ok=True)
if not destination.exists():
    # Publish a complete directory atomically. Concurrent crawls can reuse the
    # identical versioned copy; none can observe a half-copied extension.
    with tempfile.TemporaryDirectory(
        prefix=".prepare-",
        dir=destination.parent,
    ) as temporary:
        staging = Path(temporary) / "extension"
        shutil.copytree(source, staging)
        (staging / "bg.js").write_text(script)
        try:
            staging.rename(destination)
        except OSError as error:
            if error.errno not in (errno.EEXIST, errno.ENOTEMPTY):
