if (destination / "bg.js").read_text() != script:
    raise RuntimeError(
        "Prepared ArchiveWeb.page differs from pinned service-worker patch",
    )
prepared_path = (
    Path(config.CRAWL_DIR) / "chrome" / "extensions" / "archivewebpage.extension.json"
)
prepared_path.parent.mkdir(parents=True, exist_ok=True)
write_text_atomic(
    prepared_path,
    json.dumps(
        {
            "name": EXTENSION_NAME,
            "version": version,
            "unpacked_path": str(destination.resolve()),
        },
    ),
)

#!/usr/bin/env -S abxpkg run --script --binproviders=env,pnpm,apt,brew node
// /// script
// ///
/**
 * 2Captcha Extension Configuration
 *
 * Configures the 2captcha extension with API key and settings after Crawl-level Chrome session starts.
 * Runs once per crawl through the extension's login and configuration APIs.
 *
 * Priority: 95 (after chrome_launch at 90, before snapshots start)
 * Hook: on_Crawl (runs once per crawl, not per snapshot)
 *
 * Config Options (from config.json / environment):
 * - TWOCAPTCHA_API_KEY: API key for 2captcha service
 * - TWOCAPTCHA_ENABLED: Enable/disable the extension
 * - TWOCAPTCHA_RETRY_COUNT: Number of retries on error
 * - TWOCAPTCHA_RETRY_DELAY: Delay between retries (seconds)
 * - TWOCAPTCHA_AUTO_SUBMIT: Auto-submit forms after solving
 *
 * Requirements:
 * - TWOCAPTCHA_API_KEY environment variable must be set
 * - chrome plugin must have loaded browser metadata (browser.json must exist)
 */

const path = require("path");
const fs = require("fs");
const {
  PROCESS_EXIT_SKIPPED,
  ensureNodeModuleResolution,
  parseArgs,
  getEnv,
  getEnvBool,
  getEnvInt,
  loadConfig,
} = require("../base/utils.js");

const PLUGIN_DIR = path.basename(__dirname);
const hookConfig = loadConfig();
const CRAWL_DIR = path.resolve((hookConfig.CRAWL_DIR || ".").trim());
const CHROME_ISOLATION =
  String(getEnv("CHROME_ISOLATION", "crawl")).toLowerCase() === "snapshot"
    ? "snapshot"
    : "crawl";
const OUTPUT_DIR = path.join(CRAWL_DIR, PLUGIN_DIR);
if (!fs.existsSync(OUTPUT_DIR)) {
  fs.mkdirSync(OUTPUT_DIR, { recursive: true });
}
process.chdir(OUTPUT_DIR);

function getCrawlChromeSessionDir() {
  const crawlDir = hookConfig.CRAWL_DIR || ".";
  return path.join(path.resolve(crawlDir), "chrome");
}

const CHROME_SESSION_DIR = getCrawlChromeSessionDir();
const CONFIG_MARKER = path.join(CHROME_SESSION_DIR, ".twocaptcha_configured");

function chromeExtensionReadyTimeoutMs() {
  return (
    Math.max(
      getEnvInt(
        "TWOCAPTCHA_TIMEOUT",
        getEnvInt("CHROME_TIMEOUT", getEnvInt("TIMEOUT", 60))
      ),
      getEnvInt("CHROME_EXTENSION_LOAD_TIMEOUT", 30)
    ) * 1000
  );
}

function twoCaptchaLoginTimeoutMs() {
  return getEnvInt("TWOCAPTCHA_LOGIN_TIMEOUT", 20) * 1000;
}

function hasConfiguredApiKey() {
  const apiKey = (hookConfig.TWOCAPTCHA_API_KEY || "").trim();
  return !!apiKey && apiKey !== "YOUR_API_KEY_HERE";
}

/**
 * Get 2captcha configuration from environment variables.
 * Supports both TWOCAPTCHA_* and legacy API_KEY_2CAPTCHA naming.
 */
function getTwoCaptchaConfig() {
  const apiKey = (hookConfig.TWOCAPTCHA_API_KEY || "").trim();
  const isEnabled = getEnvBool("TWOCAPTCHA_ENABLED", true);
  const retryCount = getEnvInt("TWOCAPTCHA_RETRY_COUNT", 3);
  const retryDelay = getEnvInt("TWOCAPTCHA_RETRY_DELAY", 5);
  const autoSubmit = getEnvBool("TWOCAPTCHA_AUTO_SUBMIT", false);

  // Build the full config object matching the extension's storage structure
  // Structure: chrome.storage.local.set({config: {...}})
  return {
    // API key - both variants for compatibility
    apiKey: apiKey,
    api_key: apiKey,

    // Plugin enabled state
    isPluginEnabled: isEnabled,

    // Retry settings
    repeatOnErrorTimes: retryCount,
    repeatOnErrorDelay: retryDelay,

    // Auto-submit setting
    autoSubmitForms: autoSubmit,
    submitFormsDelay: 0,

    // Enable all CAPTCHA types
    enabledForNormal: true,
    enabledForRecaptchaV2: true,
    enabledForInvisibleRecaptchaV2: true,
    enabledForRecaptchaV3: true,
    enabledForRecaptchaAudio: false,
    enabledForGeetest: true,
    enabledForGeetest_v4: true,
    enabledForKeycaptcha: true,
    enabledForArkoselabs: true,
    enabledForLemin: true,
    enabledForYandex: true,
    enabledForCapyPuzzle: true,
    enabledForTurnstile: true,
    enabledForAmazonWaf: true,
    enabledForMTCaptcha: true,

    // Auto-solve all CAPTCHA types
    autoSolveNormal: true,
    autoSolveRecaptchaV2: true,
    autoSolveInvisibleRecaptchaV2: true,
    autoSolveRecaptchaV3: true,
    autoSolveRecaptchaAudio: false,
    autoSolveGeetest: true,
    autoSolveGeetest_v4: true,
    autoSolveKeycaptcha: true,
    autoSolveArkoselabs: true,
    autoSolveLemin: true,
    autoSolveYandex: true,
    autoSolveCapyPuzzle: true,
    autoSolveTurnstile: true,
    autoSolveAmazonWaf: true,
    autoSolveMTCaptcha: true,

    // Other settings with sensible defaults
    recaptchaV2Type: "token",
    recaptchaV3MinScore: 0.3,
    buttonPosition: "inner",
    useProxy: false,
    proxy: "",
    proxytype: "HTTP",
    blackListDomain: "",
    autoSubmitRules: [],
    normalSources: [],
  };
}

async function configure2Captcha() {
  if (CHROME_ISOLATION === "snapshot") {
    console.error(
      "[*] CHROME_ISOLATION=snapshot, skipping crawl-scoped 2captcha setup"
    );
    return { success: true, skipped: true };
  }

  if (!hasConfiguredApiKey()) {
    console.error(
      "[*] TWOCAPTCHA_API_KEY not configured, skipping 2captcha setup"
    );
    return { success: true, skipped: true };
  }

  ensureNodeModuleResolution(module);
  const {
    waitForChromeSessionState,
    findExtensionMetadataByName,
    connectToBrowserEndpoint,
    resolvePuppeteerModule,
  } = require("../chrome/chrome_utils.js");
  const puppeteer = resolvePuppeteerModule();

  // Get configuration
  const config = getTwoCaptchaConfig();

  // Check if API key is set
  if (!config.apiKey || config.apiKey === "YOUR_API_KEY_HERE") {
    console.warn(
      "[!] 2captcha extension loaded but TWOCAPTCHA_API_KEY not configured"
    );
    console.warn(
      "[!] Set TWOCAPTCHA_API_KEY environment variable to enable automatic CAPTCHA solving"
    );
    return { success: false, error: "TWOCAPTCHA_API_KEY not configured" };
  }

  console.error("Configuring 2captcha...");

  try {
    const chromeSession = await waitForChromeSessionState(CHROME_SESSION_DIR, {
      timeoutMs: chromeExtensionReadyTimeoutMs(),
      requireBrowserReady: true,
    });
    if (!chromeSession?.cdpUrl) {
      throw new Error("No Chrome session found (chrome plugin must run first)");
    }
    const { cdpUrl } = chromeSession;
    const browser = await connectToBrowserEndpoint(puppeteer, cdpUrl, {
      defaultViewport: null,
    });

    try {
      // Get 2captcha extension info from browser.json
      const extensions = chromeSession.extensions || [];
      const captchaExt = findExtensionMetadataByName(extensions, "twocaptcha");

      if (!captchaExt) {
        console.error(
          "[*] 2captcha extension not installed, skipping configuration"
        );
        return { success: true, skipped: true };
      }

      if (!captchaExt.id) {
        return {
          success: false,
          error: "2captcha extension ID not found in browser.json",
        };
      }

      const extensionId = captchaExt.id;
      console.error(`Extension ID: ${extensionId}`);

      // Configure through the extension's real popup login path. That path
      // initializes the service worker's in-memory API client, validates the
      // account with 2Captcha, and persists the key. Writing storage directly
      // leaves the already-running service worker unable to solve anything.
      const optionsUrl = `chrome-extension://${extensionId}/options/options.html`;

      let configPage = await browser.newPage();

      try {
        // Navigate to options page - catch error but continue since page may still load
        try {
          await configPage.goto(optionsUrl, {
            waitUntil: "networkidle0",
            timeout: 10000,
          });
        } catch (navError) {
          // Navigation may throw ERR_BLOCKED_BY_CLIENT but page still loads
          console.error(
            `[*] Navigation threw error (may still work): ${navError.message}`
          );
        }

        // Check all pages for the extension page (Chrome may open it in a different tab)
        const pages = await browser.pages();
        for (const page of pages) {
          const url = page.url();
          if (url.startsWith(`chrome-extension://${extensionId}`)) {
            configPage = page;
            break;
          }
        }

        const currentUrl = configPage.url();

        if (!currentUrl.startsWith(`chrome-extension://${extensionId}`)) {
          return {
            success: false,
            error: `Failed to navigate to options page, got: ${currentUrl}`,
          };
        }

        // Wait for the extension's options-page init to finish constructing the
        // ``Config`` global. ``waitForFunction`` polls the page's runtime
        // ~every 100ms, so it resolves as soon as the script is parsed — no
        // explicit sleep needed. The prior 3s ``setTimeout`` was a pessimistic
        // fixed delay; with ``Config`` reachable, we know the page is ready.
        await configPage.waitForFunction(() => typeof Config !== "undefined", {
          timeout: 10000,
        });

        const result = await configPage.evaluate((cfg, loginTimeoutMs) => {
          return new Promise((resolve) => {
            const popup = chrome.runtime.connect({ name: "popup" });
            const timeout = setTimeout(() => {
              popup.disconnect();
              resolve({
                success: false,
                error: `2captcha login did not respond within ${loginTimeoutMs}ms`,
              });
            }, loginTimeoutMs);
            popup.onMessage.addListener(async (message) => {
              if (message.action !== "login") return;
              clearTimeout(timeout);
              if (message.error) {
                popup.disconnect();
                resolve({ success: false, error: message.error });
                return;
              }
              await Config.set(cfg);
              popup.disconnect();
              resolve({ success: true, method: "popup_login" });
            });
            popup.postMessage({ action: "login", apiKey: cfg.apiKey });
          });
        }, config, twoCaptchaLoginTimeoutMs());

        if (result.success) {
          console.log(`Configured via ${result.method}`);

          // Verify the extension's persisted configuration after its login and
          // Config.set APIs have both completed.
          const verifyConfig = await configPage.evaluate(() => {
            return new Promise((resolve) => {
              if (typeof chrome === "undefined" || !chrome.storage) {
                resolve(null);
                return;
              }
              chrome.storage.local.get("config", (data) => {
                resolve((data && data.config) || null);
              });
            });
          });

          if (!verifyConfig) {
            return {
              success: false,
              error: "Could not verify config - chrome.storage.local empty after set",
            };
          }

          // Check that API key was actually set
          const actualApiKey = verifyConfig.apiKey || verifyConfig.api_key;
          if (!actualApiKey || actualApiKey !== config.apiKey) {
            console.error(`[!] Config verification FAILED - API key mismatch`);
            return {
              success: false,
              error: "Config verification failed - API key not set correctly",
            };
          }

          console.log("Ready.");

          fs.writeFileSync(
            CONFIG_MARKER,
            JSON.stringify(
              {
                timestamp: new Date().toISOString(),
                method: result.method,
                extensionId: extensionId,
                verified: true,
                config: {
                  apiKeySet: !!config.apiKey,
                  isPluginEnabled: config.isPluginEnabled,
                  repeatOnErrorTimes: config.repeatOnErrorTimes,
                  repeatOnErrorDelay: config.repeatOnErrorDelay,
                  autoSubmitForms: config.autoSubmitForms,
                  autoSolveEnabled: true,
                },
              },
              null,
              2
            )
          );
          return { success: true, method: result.method, verified: true };
        }

        return { success: false, error: result.error || "Config failed" };
      } finally {
        try {
          await configPage.close();
        } catch (e) {}
        for (const page of await browser.pages()) {
          const url = page.url() || "";
          if (!url.startsWith(`chrome-extension://${extensionId}/options/`)) {
            continue;
          }
          try {
            await page.close();
          } catch (e) {}
        }
      }
    } finally {
      browser.disconnect();
    }
  } catch (e) {
    return { success: false, error: `${e.name}: ${e.message}` };
  }
}

async function main() {
  const args = parseArgs();
  const url = args.url;

  if (!url) {
    console.error("Usage: on_CrawlSetup__95_twocaptcha_config.js --url=<url>");
    process.exit(1);
  }

  const startTs = new Date();
  let status = "failed";
  let error = "";

  try {
    console.log("2Captcha configuration started");
    const result = await configure2Captcha();

    if (result.skipped) {
      status = "skipped";
    } else if (result.success) {
      status = "succeeded";
    } else {
      status = "failed";
      error = result.error || "Configuration failed";
    }
  } catch (e) {
    error = `${e.name}: ${e.message}`;
    status = "failed";
  }

  const endTs = new Date();
  const duration = (endTs - startTs) / 1000;

  if (error) {
    console.error(`ERROR: ${error}`);
  }

  // Config hooks don't emit JSONL - they're utility hooks for setup
  // Exit code indicates success/failure

  process.exit(
    status === "skipped" ? PROCESS_EXIT_SKIPPED : status === "succeeded" ? 0 : 1
  );
}

main().catch((e) => {
  console.error(`Fatal error: ${e.message}`);
  process.exit(1);
});

#!/usr/bin/env -S abxpkg run --script --deps-from=./config.json:required_binaries node
// /// script
// ///
/**
 * Launch a shared Chromium browser session for the entire crawl.
 *
 * This runs once per crawl and keeps Chromium alive for all snapshots to share.
 * Each snapshot creates its own tab via on_Snapshot__01_chrome_tab.daemon.bg.js.
 *
 * Extension caches are loaded after startup through CDP so Chrome assigns and
 * publishes the real runtime extension IDs in browser.json.
 *
 * Usage: on_CrawlSetup__90_chrome_launch.daemon.bg.js
 * Output: Writes to current directory (executor creates chrome/ dir):
 *   - cdp_url.txt: WebSocket/HTTP URL for CDP connection
 *   - chrome.pid: Chromium process ID (for cleanup)
 *   - browser.json: Browser setup metadata and loaded extensions
 *
 * Environment variables:
 *     NODE_MODULES_DIR: Path to node_modules directory for module resolution
 *     CHROME_BINARY: Chromium binary path resolved by abxpkg
 *     CHROME_RESOLUTION: Page resolution (default: 1440,2000)
 *     CHROME_HEADLESS: Run in headless mode (default: true)
 *     CHROME_CHECK_SSL_VALIDITY: Whether to check SSL certificates (default: true)
 *     CHROMEWEBSTORE_EXTENSIONS_DIR: Directory containing Chrome Web Store extension artifacts
 */


const installShutdownHandler = require("../base/daemon_lifecycle.js").captureShutdownSignals();

const fs = require("fs");
const path = require("path");
const { ensureNodeModuleResolution, loadConfig } = require("../base/utils.js");
ensureNodeModuleResolution(module);
const {
  acquireSessionLock,
  ensureChromeSession,
  closeBrowserInChromeSession,
  getChromeSessionOptionsFromConfig,
  getChromeLaunchPrerequisites,
  startBrowserExportSweep,
} = require("./chrome_utils.js");

// Extractor metadata
const PLUGIN_NAME = "chrome_launch";
const PLUGIN_DIR = path.basename(__dirname);
// A new browser must not inherit a previous session's saved persona identity.
const hookConfig = loadConfig(null, { hydrateUserAgent: false });
const CRAWL_DIR = path.resolve((hookConfig.CRAWL_DIR || ".").trim());
const chromeSessionOptions = getChromeSessionOptionsFromConfig(hookConfig);
const CHROME_USER_DATA_DIR = chromeSessionOptions.CHROME_USER_DATA_DIR;
const CHROME_CDP_URL = chromeSessionOptions.CHROME_CDP_URL;
const CHROME_IS_LOCAL = chromeSessionOptions.CHROME_IS_LOCAL;
const CHROME_KEEPALIVE = hookConfig.CHROME_KEEPALIVE === true;
const CHROME_ISOLATION =
  String(hookConfig.CHROME_ISOLATION || "crawl").toLowerCase() === "snapshot"
    ? "snapshot"
    : "crawl";
const OUTPUT_DIR = path.join(CRAWL_DIR, PLUGIN_DIR);
if (!fs.existsSync(OUTPUT_DIR)) {
  fs.mkdirSync(OUTPUT_DIR, { recursive: true });
}
process.chdir(OUTPUT_DIR);
const CHROME_BINARY = String(hookConfig.CHROME_BINARY || "chromium")
  .split("/")
  .at(-1);
const PERSONA_DIR =
  CHROME_USER_DATA_DIR ||
  path.join(
    hookConfig.PERSONAS_DIR || "~/.config/abx/personas",
    hookConfig.ACTIVE_PERSONA || "Default"
  );

// Global state for cleanup
let chromePid = null;
let chromeCdpUrl = null;
let chromeProcessIsLocal = CHROME_IS_LOCAL;
let shouldCloseOnCleanup = false;
let puppeteer = null;
let cleanupPromise = null;
let launchInProgress = true;
let cleanupRequestedDuringLaunch = false;
let launchPublished = false;
let stopExportSweep = null;

function recordLaunch(pid) {
  chromePid = pid;
}

function recordCdpSession(session, shouldClose) {
  chromePid = session.pid;
  chromeCdpUrl = session.cdpUrl;
  shouldCloseOnCleanup = shouldClose;
}

function publishReadiness(session, shouldClose) {
  recordCdpSession(session, shouldClose);
  if (!launchPublished) {
    launchPublished = true;
    console.log(`[+] ${CHROME_BINARY} session started`);
  }
}

// Cleanup handler for SIGTERM
async function cleanup() {
  if (cleanupPromise) {
    return cleanupPromise;
  }
  if (launchInProgress && !chromeCdpUrl) {
    cleanupRequestedDuringLaunch = true;
    if (!chromeProcessIsLocal) {
      console.error(
        "[*] Deferring external Chrome cleanup until launch publishes its CDP session"
      );
      return;
    }
    const launchStatePublished = ["chrome.pid", "cdp_url.txt"].some(
      (fileName) => fs.existsSync(path.join(OUTPUT_DIR, fileName))
    );
    if (launchStatePublished) {
      console.error(
        "[*] Cleaning up in-progress local Chrome from persisted state"
      );
    } else {
      console.error(
        "[*] Deferring chrome cleanup until launch publishes local session state"
      );
      return;
    }
  }
  const cleanupDuringLocalLaunch =
    cleanupRequestedDuringLaunch && chromeProcessIsLocal;
  cleanupPromise = (async () => {
    if (stopExportSweep) {
      try {
        await stopExportSweep();
      } catch (error) {
        console.error(`[*] Could not close browser export targets: ${error.message}`);
      }
    }
    if (shouldCloseOnCleanup || cleanupDuringLocalLaunch) {
      console.error(`shutting down ${CHROME_BINARY} cleanly...`);
      const closed = await closeBrowserInChromeSession({
        cdpUrl: chromeCdpUrl,
        pid: chromePid,
        outputDir: OUTPUT_DIR,
        puppeteer,
        processIsLocal: chromeProcessIsLocal,
      });
      if (!closed) {
        console.error(
          `${CHROME_BINARY} cleanup did not fully stop the browser process tree`
        );
        process.exit(1);
      }
      console.error(`${CHROME_BINARY} exited successfully`);
      console.log(JSON.stringify({ succeeded: true, skipped: false })); // we launched and we killed it (nothing was skipped)
    } else {
      if (!chromeCdpUrl) {
        console.error(
          `${CHROME_BINARY} cleanup requested before a CDP session was published`
        );
        process.exit(1);
      }
      console.error(`leaving ${CHROME_BINARY} running (CHROME_KEEPALIVE=True)`);
      console.log(
        JSON.stringify({
          succeeded: true,
          skipped: chromeCdpUrl ? true : false,
        })
      ); // we didn't launch it (we connected over CDP), and we didn't kill it, so we skipped basically the whole hook
    }
    process.exit(0);
  })();
  return cleanupPromise;
}

// Register signal handlers
installShutdownHandler(cleanup);

async function main() {
  let releaseLock = null;

  try {
    console.error("waiting for other chrome instances to finish launching...");
    releaseLock = await acquireSessionLock(
      path.join(OUTPUT_DIR, ".launch.lock")
    );
    const isolation = CHROME_ISOLATION;
    const keepAlive = CHROME_KEEPALIVE;
    const cdpUrlOverride = CHROME_CDP_URL;
    chromeProcessIsLocal = CHROME_IS_LOCAL;

    if (isolation === "snapshot") {
      console.error(
        "skipping crawl-scoped browser launch (CHROME_ISOLATION=snapshot)"
      );
      releaseLock();
      releaseLock = null;
      process.exit(0);
    }

    const prerequisites = getChromeLaunchPrerequisites({
      requireLocalBinary: !cdpUrlOverride && chromeProcessIsLocal,
    });
    puppeteer = prerequisites.puppeteer;

    console.error(
      cdpUrlOverride
        ? `connecting ${CHROME_BINARY} ${cdpUrlOverride}...`
        : `launching ${CHROME_BINARY} ${PERSONA_DIR}...`
    );
    launchInProgress = true;
    const session = await ensureChromeSession({
      outputDir: OUTPUT_DIR,
      puppeteer,
      binary: prerequisites.binary || null,
      ...chromeSessionOptions,
      CHROME_IS_LOCAL: chromeProcessIsLocal,
      CHROME_CDP_URL: cdpUrlOverride,
      // These callbacks expose private state for cancellation cleanup only.
      // stdout is the daemon protocol's public readiness boundary and must not
      // be emitted until ensureChromeSession finishes extension/cookie setup.
      onSpawn: (spawnedSession) => recordLaunch(spawnedSession.pid),
      onCdpReady: (readySession) =>
        recordCdpSession(readySession, !keepAlive),
    });
    launchInProgress = false;

    publishReadiness(session, !keepAlive);
    stopExportSweep = startBrowserExportSweep({ chromeSessionDir: OUTPUT_DIR,
      cdpUrl: chromeCdpUrl, puppeteer });

    for (const extension of session.installedExtensions) {
      console.error(
        `${extension.load_on_demand ? "extension available on demand" : "loading extension"}: ${
          extension.name || extension.id || extension.unpacked_path
        }${extension.load_on_demand ? "" : "..."}`
      );
    }
    if (session.reusedExisting) {
      console.error(`reusing live ${CHROME_BINARY} session in ${OUTPUT_DIR}`);
    }

    console.error(`[+] CDP URL: ${chromeCdpUrl}`);
    releaseLock();
    releaseLock = null;

    if (cleanupRequestedDuringLaunch) {
      console.error(
        `[*] Running deferred ${CHROME_BINARY} cleanup requested during launch`
      );
      await cleanup();
      return;
    }


    console.error(
      `${CHROME_BINARY} running pid=${
        chromePid || "remote"
      }, waiting for cleanup...`
    );
  } catch (e) {
    if (cleanupRequestedDuringLaunch && cleanupPromise) {
      await cleanupPromise;
      return;
    }
    if (chromeCdpUrl || chromePid) {
      try {
        await closeBrowserInChromeSession({
          cdpUrl: chromeCdpUrl,
          pid: chromePid,
          outputDir: OUTPUT_DIR,
          puppeteer,
          processIsLocal: chromeProcessIsLocal,
        });
      } catch (cleanupError) {}
    }
    if (releaseLock) {
      releaseLock();
    }
    launchInProgress = false;
    console.error(`ERROR: ${e.name}: ${e.message}`);
    process.exit(1);
  }
}

main().catch((e) => {
  console.error(`Fatal error: ${e.message}`);
  process.exit(1);
});

"""A timed-out real browser installer must not survive its owning bootstrap."""

import signal
import subprocess
import threading

import psutil
import pytest

from abx_plugins.plugins.chrome.tests.chrome_test_helpers import (
    _run_chrome_required_binary_env,
    get_test_env,
)


def test_chrome_bootstrap_timeout_reaps_real_browser_installer(
    tmp_path,
    ensure_chrome_test_prereqs,
):
    env = get_test_env()
    env.update(
        {
            "CHROME_BINARY": "chromium",
            "ABXPKG_PUPPETEER_ROOT": str(tmp_path / "puppeteer"),
        },
    )
    finished = threading.Event()
    stopped = threading.Event()
    installers = []
    monitor_errors = []

    def signal_process(process, signum):
        try:
            process.send_signal(signum)
        except psutil.AccessDenied:
            subprocess.run(
                ["sudo", "-n", "--", "kill", f"-{signum}", str(process.pid)],
                check=True,
                capture_output=True,
                timeout=5,
            )

    def stop_installer():
        try:
            parent = psutil.Process()
            while not finished.wait(0.02):
                for process in parent.children(recursive=True):
                    try:
                        command = process.cmdline()
                        if (
                            process.name() == "node"
                            and "install" in command
                            and any(arg.startswith("chrome@") for arg in command)
                            and any("puppeteer" in arg for arg in command)
                        ):
                            installers.extend(
                                [process, *process.children(recursive=True)],
                            )
                            signal_process(process, signal.SIGSTOP)
                            stopped.set()
                            return
                    except (
                        psutil.NoSuchProcess,
                        psutil.ZombieProcess,
                        psutil.AccessDenied,
                    ):
                        continue
        except BaseException as error:
            monitor_errors.append(error)

    monitor = threading.Thread(target=stop_installer)
    monitor.start()
    try:
        with pytest.raises(subprocess.TimeoutExpired) as timeout:
            result = _run_chrome_required_binary_env(env, timeout=20)
            pytest.fail(f"Installer returned {result.returncode}: {result.stderr}")
        assert not monitor_errors, monitor_errors
        assert stopped.is_set(), "The real Puppeteer installer did not start"
        assert "Installing chromium via puppeteer" in str(timeout.value.stderr)
        assert installers
        _, alive = psutil.wait_procs(installers, timeout=5)
        assert not alive, (
            f"Browser installers survived bootstrap timeout: {[process.pid for process in alive]}"
        )
    finally:
        finished.set()
        monitor.join(timeout=5)
        for process in reversed(installers):
            try:
                signal_process(process, signal.SIGKILL)
            except (psutil.NoSuchProcess, psutil.ZombieProcess):
                pass
        psutil.wait_procs(installers, timeout=5)

"""The managed capture browser must use the committed stable Chrome release."""

import json
import subprocess

from abx_plugins.plugins.chrome.tests.chrome_test_helpers import (
    CHROME_UTILS,
    chrome_session,
    get_test_env,
)


def test_managed_browser_is_stable_chrome(
    tmp_path,
    httpserver,
    ensure_chrome_test_prereqs,
):
    env = get_test_env()
    version = subprocess.run(
        [env["CHROME_BINARY"], "--version"],
        env=env,
        capture_output=True,
        text=True,
        check=True,
        timeout=10,
    )
    # Official Chrome for Testing stable release, independently checked against
    # its published channel manifest when updating the dependency pin.
    assert "Google Chrome for Testing 155.0.8059.84" in version.stdout
    httpserver.expect_request("/").respond_with_data(
        "<!doctype html><title>Stable Chrome capture</title><h1>ArchiveBox</h1>",
        content_type="text/html",
    )
    with chrome_session(tmp_path, test_url=httpserver.url_for("/"), timeout=30) as (
        _,
        _,
        chrome,
        runtime,
    ):
        result = subprocess.run(
            [
                runtime["NODE_BINARY"],
                "-e",
                """
const utils = require(process.argv[1]);
(async () => {
  const {browser, page} = await utils.connectToPage({chromeSessionDir: process.argv[2]});
  try {
    console.log(JSON.stringify({version: await browser.version(), title: await page.title()}));
  } finally { await browser.disconnect(); }
})().catch(error => { console.error(error); process.exitCode = 1; });
""",
                str(CHROME_UTILS),
                str(chrome),
            ],
            env=runtime,
            capture_output=True,
            text=True,
            timeout=10,
        )
        assert result.returncode == 0, result.stderr
        assert json.loads(result.stdout) == {
            "version": "Chrome/155.0.8059.84",
            "title": "Stable Chrome capture",
        }
